recipes.code:
{
  "inputs": [
    {
      "id": "hptsu-api-key",
      "type": "promptString",
      "description": "X-API-Key issued in the hpt.su cabinet (requires MCP_FREE or MCP_PAID scope).",
      "password": true
    }
  ],
  "servers": {
    "hptsu": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "hptsu-mcp@0.4.1"
      ],
      "env": {
        "HPTSU_API_KEY": "${input:hptsu-api-key}",
        "HPTSU_BASE_URL": "https://hpt.su/api/v1"
      }
    }
  }
}
